<script setup lang="ts">
import{computed,onMounted,reactive,ref}from'vue';import{cambiarCategorias,listarRecategorizaciones,type Recategorizacion}from'../services/recategorizar'
const rows=ref<Recategorizacion[]>([]),selected=ref<Recategorizacion|null>(null),loading=ref(false),saving=ref(false),search=ref(''),error=ref(''),success=ref(''),choices=reactive<Record<number,number>>({});const filtered=computed(()=>{const q=search.value.toLowerCase();return rows.value.filter(x=>`${x.cliente} ${x.codigo} ${x.codigo_sici||''} ${x.direccion}`.toLowerCase().includes(q))})
async function load(){loading.value=true;error.value='';try{rows.value=await listarRecategorizaciones()}catch(e){error.value=msg(e)}finally{loading.value=false}}function open(x:Recategorizacion){selected.value=x;Object.keys(choices).forEach(k=>delete choices[Number(k)]);x.unidades_uso.forEach(u=>choices[u.id]=u.categoria_id);error.value=''}function changed(x:Recategorizacion){return x.unidades_uso.filter(u=>choices[u.id]!==u.categoria_id).length}async function save(){const x=selected.value;if(!x)return;const count=changed(x);if(!count){error.value='Seleccione al menos una categoría diferente a la actual.';return}if(!confirm(`Se actualizarán ${count} unidad(es) de uso y se cerrará la solicitud. ¿Continuar?`))return;saving.value=true;error.value='';try{await cambiarCategorias(x.id,{categorias:{...choices}});rows.value=rows.value.filter(r=>r.id!==x.id);selected.value=null;success.value='Categorías actualizadas y solicitud cerrada correctamente.'}catch(e){error.value=msg(e)}finally{saving.value=false}}function msg(e:unknown){return e instanceof Error?e.message:'No se pudo completar la operación.'}onMounted(load)
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / EVAN / Catastro / Recategorizar</nav><header class="hero"><div class="mark">⇄</div><div><small>EVAN · CATASTRO COMERCIAL</small><h1>Cambios de categoría</h1><p>Evaluación de solicitudes y actualización de unidades de uso.</p></div><div class="counter"><b>{{rows.length}}</b><span>solicitudes pendientes</span></div></header><p v-if="success" class="flash good">✓ {{success}}</p><p v-if="error" class="flash bad">{{error}}</p><section class="search"><label>Buscar solicitud<input v-model.trim="search" placeholder="Cliente, inscripción o dirección"></label></section><div v-if="loading" class="empty">Cargando solicitudes…</div><div v-else-if="!filtered.length" class="empty"><b>Sin cambios pendientes</b><span>No existen solicitudes de recategorización abiertas.</span></div><section v-else class="cards"><article v-for="x in filtered" :key="x.id"><div v-if="x.fotografia_url" class="photo" :style="{backgroundImage:`url(${x.fotografia_url})`}"></div><div v-else class="photo fallback">Sin fotografía</div><div class="body"><small>SOLICITUD {{x.fecha_solicitud}}</small><h2>{{x.cliente}}</h2><p>{{x.direccion}}</p><dl><div><dt>Inscripción</dt><dd>{{x.codigo}}</dd></div><div><dt>Categoría actual</dt><dd>{{x.unidades_uso[0]?.categoria||'—'}}</dd></div><div><dt>Unidades</dt><dd>{{x.unidades_uso.length}}</dd></div></dl><button @click="open(x)">Cambiar categoría</button></div></article></section>
<div v-if="selected" class="backdrop" @mousedown.self="selected=null"><section class="modal"><header><div><small>CONEXIÓN {{selected.codigo}}</small><h2>{{selected.cliente}}</h2><p>{{selected.documento||'Sin documento registrado'}}</p></div><button class="x" @click="selected=null">×</button></header><section class="location"><h3>Ubicación catastral</h3><div><span><b>Distrito</b>{{selected.distrito}}</span><span><b>Sector</b>{{selected.sector}}</span><span><b>Manzana</b>{{selected.manzana}}</span><span><b>Lote</b>{{selected.lote}}</span></div><p>{{selected.direccion}}</p></section><section class="change"><h3>Cambio de categoría</h3><div class="table"><header><span>#</span><span>Categoría actual</span><span>Nueva categoría</span></header><article v-for="(u,i) in selected.unidades_uso" :key="u.id" :class="{modified:choices[u.id]!==u.categoria_id}"><span>{{i+1}}</span><b>{{u.categoria}}</b><select v-model.number="choices[u.id]"><option v-for="c in selected.categorias" :key="c.id" :value="c.id">{{c.nombre}}</option></select></article></div></section><footer><span>{{changed(selected)}} cambio(s) seleccionado(s)</span><button class="clear" @click="selected=null">Cancelar</button><button :disabled="saving||!changed(selected)" @click="save">{{saving?'Actualizando…':'Confirmar cambio'}}</button></footer></section></div></div></template>
<style scoped>
.page{--a:#7b57a3;color:#35454c}nav{margin-bottom:16px;color:#929da2;font-size:.7rem}nav a{color:var(--a)}.hero{padding:22px 25px;display:flex;align-items:center;gap:15px;border-left:5px solid var(--a);border-radius:13px;background:#fff}.mark{width:52px;height:52px;display:grid;place-items:center;border-radius:11px;color:#fff;background:var(--a);font-size:1.25rem;font-weight:800}.hero small,.modal small,.cards small{color:var(--a);font-size:.52rem;font-weight:750}.hero h1{margin:2px 0;font-size:1.28rem}.hero p,.modal header p{margin:0;color:#7d898e;font-size:.62rem}.counter{margin-left:auto;text-align:right}.counter b,.counter span{display:block}.counter b{color:var(--a);font-size:1.1rem}.counter span{font-size:.45rem}.flash{padding:10px;font-size:.6rem}.good{color:#277259;background:#eaf8f1}.bad{color:#9d3d42;background:#fff0f0}.search{margin-top:12px;padding:12px;background:#fff}.search label{font-size:.48rem}input,select{width:100%;padding:8px;border:1px solid #d7e0e3;border-radius:5px;font:inherit;font-size:.52rem}.cards{margin-top:12px;display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.cards article{overflow:hidden;border-radius:8px;background:#fff}.photo{height:105px;background-position:center;background-size:cover}.fallback{display:grid;place-items:center;color:#9b8aa9;background:#eee9f3;font-size:.48rem}.body{padding:12px}.body h2{margin:3px 0;font-size:.72rem}.body p{min-height:27px;margin:0;color:#748187;font-size:.47rem}.body dl{display:grid;grid-template-columns:1fr 1fr .6fr;margin:10px 0;background:#f6f4f8}.body dl div{padding:7px;border-right:1px solid #e5e0e9}.body dt{color:#889298;font-size:.4rem}.body dd{margin:2px 0;font-size:.5rem;font-weight:700}.body button,.modal footer button{padding:8px 10px;border:0;border-radius:4px;color:#fff;background:var(--a);font-size:.47rem}.empty{margin-top:12px;padding:45px;display:grid;gap:5px;text-align:center;background:#fff;font-size:.58rem}.empty span{color:#8a959a}.backdrop{position:fixed;z-index:100;inset:0;padding:16px;display:grid;place-items:center;background:#14283888}.modal{width:min(100%,760px);max-height:94vh;overflow:auto;padding:20px;border-radius:12px;background:#fff}.modal>header{display:flex}.modal h2{margin:2px 0;font-size:.9rem}.x{margin-left:auto;border:0;background:none;font-size:1.4rem}.modal h3{margin:0 0 8px;font-size:.62rem}.location,.change{margin-top:14px;padding:13px;border:1px solid #e2e6e8;border-radius:7px}.location>div{display:grid;grid-template-columns:repeat(4,1fr);gap:6px}.location span{font-size:.5rem}.location b{display:block;color:#889298;font-size:.4rem}.location p{margin:9px 0 0;padding-top:8px;border-top:1px solid #e6e9ea;font-size:.5rem}.table>header,.table>article{padding:7px;display:grid;grid-template-columns:.3fr 1fr 1.4fr;align-items:center;gap:8px;border-bottom:1px solid #e8ebec;font-size:.48rem}.table>header{color:#899399;background:#f5f7f7;font-size:.42rem}.modified{background:#f4eef9}.modal>footer{margin-top:15px;display:flex;align-items:center;justify-content:flex-end;gap:6px}.modal>footer span{margin-right:auto;color:var(--a);font-size:.48rem}.modal .clear{color:#65737a;background:#edf1f2}.modal button:disabled{opacity:.4}@media(max-width:850px){.cards{grid-template-columns:1fr 1fr}}@media(max-width:560px){.hero{flex-wrap:wrap}.counter{margin-left:0}.cards{grid-template-columns:1fr}.location>div{grid-template-columns:1fr 1fr}}
</style>
